{
  "vulnerable_symbols": [
    "axios.request"
  ],
  "trigger": "在 Node.js 等环境中使用 axios 的 fetch adapter 发起请求，且同进程 Object.prototype 已被污染（如 headers），使 fetchOptions 继承敏感字段。",
  "exploit_evidence": [],
  "fixed_version": "1.20.0",
  "summary_zh": "Axios fetch 适配器误传原始 fetchOptions，若同进程原型污染可篡改出站请求头，升级 1.20.0。"
}
